-- Everything in one go: paste into Supabase → SQL Editor → New query → Run.
-- Generated by `npm run seeds` from schema.sql and seed.sql. Don't edit by hand.

-- Court & Capital database.
-- Safe to run more than once. Paste setup.sql (this file plus the seed editions) into
-- Supabase → SQL Editor → New query → Run.

-- One row per published edition. `content` holds the whole edition as JSON
-- (pipeline/src/schema.ts → Edition); the other columns make listing cheap.
create table if not exists public.editions (
  id uuid primary key default gen_random_uuid(),
  edition_date date not null unique,
  number integer not null,
  big_story text not null,
  content jsonb not null,
  schema_version integer not null default 1,
  model text,
  published_at timestamptz not null default now()
);

create index if not exists editions_by_date on public.editions (edition_date desc);

-- Every generation attempt, for debugging. Not visible to the app.
create table if not exists public.generation_runs (
  id bigint generated always as identity primary key,
  edition_date date not null,
  trigger text not null,
  attempt integer not null,
  status text not null check (status in ('succeeded', 'failed', 'skipped')),
  error text,
  model text,
  usage jsonb,
  warnings jsonb,
  started_at timestamptz not null,
  finished_at timestamptz not null default now()
);

create index if not exists generation_runs_by_date on public.generation_runs (edition_date desc, finished_at desc);

-- Access. The app uses the publishable (anon) key: it may read editions and nothing else.
-- The pipeline uses the secret (service role) key, which bypasses row-level security.
alter table public.editions enable row level security;
alter table public.generation_runs enable row level security;

drop policy if exists "Anyone can read editions" on public.editions;
create policy "Anyone can read editions" on public.editions
  for select to anon, authenticated
  using (true);

revoke all on public.editions from anon, authenticated;
grant select on public.editions to anon, authenticated;
revoke all on public.generation_runs from anon, authenticated;

grant all on public.editions to service_role;
grant all on public.generation_runs to service_role;

-- Example editions so the app has something to show before the pipeline runs.
-- Generated by `npm run seeds` in pipeline/ from pipeline/seeds/*.json. Don't edit by hand.

insert into public.editions (edition_date, number, big_story, content, schema_version, model, published_at)
values ('2026-10-07', 200, 'Paramount closed its $110 billion takeover of Warner Bros. Discovery on Tuesday, a day after Justice Kagan refused a last-minute bid to block it, creating the media giant Skydance — while the S&P 500 hit its first record close since August.', $seed${"schema_version":1,"date":"2026-10-07","number":200,"volume":1,"big_story":{"text":"Paramount closed its $110 billion takeover of Warner Bros. Discovery on Tuesday, a day after Justice Kagan refused a last-minute bid to block it, creating the media giant Skydance — while the S&P 500 hit its first record close since August.","story_id":"paramount-warner"},"markets":{"as_of":"2026-10-06","quotes":[{"name":"S&P 500","level":7818.93,"change":0.58,"change_unit":"percent","unit":"index"},{"name":"Nasdaq","level":27599.79,"change":0.45,"change_unit":"percent","unit":"index"},{"name":"SMI","level":13788.93,"change":0.62,"change_unit":"percent","unit":"index"},{"name":"US 10Y","level":5.269,"change":-4.2,"change_unit":"bp","unit":"yield"},{"name":"USD/CHF","level":0.8311,"change":0.36,"change_unit":"percent","unit":"fx"},{"name":"Brent","level":100.58,"change":0.26,"change_unit":"percent","unit":"usd"}]},"sections":[{"key":"corporate_law","numeral":"I","title":"Corporate Law","note":"US focus","stories":[{"id":"paramount-warner","headline":"Paramount closes $110B Warner Bros. takeover after Supreme Court refuses to block it","region":"US","whos_who":[{"name":"Paramount","description":"US film/TV group run by David Ellison"},{"name":"Warner Bros. Discovery","description":"owner of Warner studios, HBO Max, CNN"},{"name":"Skydance","description":"new name of the combined company"},{"name":"Elena Kagan","description":"Supreme Court justice handling 9th Circuit emergencies"}],"body":"On Monday Justice Kagan denied, without explanation, an emergency application from consumers who wanted the merger halted; lower courts and the 9th Circuit had already rejected them. The deal closed Tuesday, with Warner shareholders receiving about $31 per share in cash. To settle suits by 12 state attorneys general and the Writers Guild, Paramount promised 30 films a year for two years, to keep both Los Angeles studio lots for five years, and an editorial board to protect CNN's and CBS News' independence.","why_it_matters":"It ends one of the biggest merger fights of the year with no federal challenge, and puts CNN, CBS News, HBO Max and Paramount+ under one owner targeting about $6B in cost savings — which likely means job cuts.","plain_words":["Two of Hollywood's biggest companies are now one.","Some customers tried at the last minute to get the highest court to stop it, but it said no.","The new company owns Harry Potter, CNN and many TV channels, and plans to save money, probably by cutting jobs."],"sources":[{"outlet":"CBS News","url":"https://www.cbsnews.com/news/paramount-warner-bros-discovery-deal-skydance/"},{"outlet":"Washington Examiner","url":"https://washingtonexaminer.com/news/supreme-court/4755031/supreme-court-kagan-paramount-warner-bros-merger"},{"outlet":"Law360","url":"https://www.law360.com/washington/articles/2534192"}],"reading_minutes":1},{"id":"intel-401k","headline":"Supreme Court appears ready to side with Intel against workers in 401(k) investment suit","region":"US","whos_who":[{"name":"Intel","description":"big US chipmaker"},{"name":"401(k)","description":"US workplace retirement savings plan"},{"name":"ERISA","description":"federal law protecting worker retirement plans"},{"name":"9th Circuit","description":"federal appeals court for the western US"}],"body":"At Tuesday's argument in *Anderson v. Intel*, a majority of justices signalled that workers who say their plan's investments underperformed must point to a \"meaningful benchmark\" *(a comparable fund with similar goals and risks)*. Intel's plan put up to about 37% of one fund into hedge funds, private equity and commodities after 2008; the 9th Circuit threw out the suit because the workers compared it with ordinary stock-heavy funds. Justice Kagan said a benchmark must be \"meaningfully similar — that doesn't mean identical,\" while others questioned how detailed the Court's guidance should be.","why_it_matters":"The ruling will set how easily employees can sue over retirement-plan choices; a tough benchmark rule would end many lawsuits early and make it safer for plans to add private-equity and other alternative investments.","plain_words":["Intel workers say the company put their retirement money into risky, expensive investments that did badly.","The judges seemed to think you can only call an investment bad if you compare it with something truly similar.","That would make it harder for workers to win cases like this."],"sources":[{"outlet":"Bloomberg Law","url":"https://news.bloomberglaw.com/employee-benefits/justices-debate-how-much-guidance-to-give-on-401k-benchmarks"},{"outlet":"PLANSPONSOR","url":"https://www.plansponsor.com/supreme-court-probes-meaningful-benchmark-definition-in-intel-oral-arguments/"}],"reading_minutes":1},{"id":"groq-delaware","headline":"Groq investors sue its former board in Delaware over Nvidia's $20B \"reverse acqui-hire\"","region":"US","whos_who":[{"name":"Groq","description":"US maker of AI inference chips"},{"name":"Nvidia","description":"world's most valuable chipmaker"},{"name":"Jonathan Ross","description":"Groq founder, now at Nvidia"},{"name":"Court of Chancery","description":"Delaware's specialist business court"}],"body":"Two former Groq engineers and shareholders filed a proposed class action, unsealed on Monday, accusing Groq's board and Ross of breaching their fiduciary duties *(the legal duty to act in all shareholders' best interest)*. In December 2025 Nvidia paid about $20B to license Groq's technology and hire Ross and around 200 engineers — a \"reverse acqui-hire\" *(buying a startup's people and tech without buying the company itself)*. The plaintiffs say the structure skipped a shareholder vote and left remaining investors with a weakened shell; Nvidia is not a defendant and Groq calls the suit meritless.","why_it_matters":"Big Tech has used this deal structure to grab AI talent while avoiding merger reviews; a Delaware ruling could decide whether boards owe ordinary shareholders the same protections as in a normal takeover.","plain_words":["Nvidia took Groq's best ideas and engineers without officially buying the company.","Some Groq shareholders say the bosses got rich while they were left with a weaker business.","They want a judge to make it right."],"sources":[{"outlet":"Bloomberg Law","url":"https://news.bloomberglaw.com/esg/nvidias-20-billion-groq-deal-draws-investor-court-challenge"},{"outlet":"Law360","url":"https://www.law360.com/delaware/articles/2534113"},{"outlet":"Cryptopolitan","url":"https://www.cryptopolitan.com/groq-shareholders-sue-nvidia-20-billion-deal/"}],"reading_minutes":1},{"id":"coinbase-texas","headline":"Texas court applies Texas law to past Coinbase conduct and throws out shareholder suit","region":"US","whos_who":[{"name":"Coinbase","description":"biggest US crypto exchange"},{"name":"Texas Business Court","description":"new Texas court for company disputes"},{"name":"Delaware","description":"state where most big US companies are incorporated"}],"body":"Judge Andrea Bouressa dismissed a derivative suit *(a case shareholders bring on the company's behalf against its own managers)* against Coinbase executives on Monday. She ruled that Texas law governs because Coinbase moved its incorporation from Delaware to Texas in December 2025 — even for conduct from before the move — calling it a bright-line rule that brings \"clarity and certainty.\"","why_it_matters":"It is an early test of whether leaving Delaware for Texas, whose 2025 reforms make shareholder suits harder, also shields managers from claims about the past; that could push more companies to reincorporate.","plain_words":["Coinbase moved its legal home from Delaware to Texas, where the rules are friendlier to company bosses.","A Texas judge said the Texas rules apply even to things that happened before the move.","So the shareholders' case against the bosses was thrown out."],"sources":[{"outlet":"Bloomberg Law","url":"https://news.bloomberglaw.com/business-and-practice/coinbase-secures-texas-derivative-dismissal-citing-delaware-exit-5"},{"outlet":"Law360","url":"https://www.law360.com/texas/articles/2533847"}],"reading_minutes":1}]},{"key":"finance","numeral":"II","title":"Finance","note":"US & Swiss markets","stories":[{"id":"sp500-record","headline":"S&P 500 tops 7,800 for first record close since August as Treasury yields retreat","region":"US","whos_who":[{"name":"S&P 500","description":"index of 500 biggest US companies"},{"name":"US Treasuries","description":"loans to the US government"},{"name":"Nvidia","description":"AI chipmaker, world's most valuable company"},{"name":"Brent","description":"global benchmark oil price"}],"body":"The S&P 500 rose 0.58% to 7,818.93 and the Nasdaq 0.45% to a record 27,599.79, led by tech as Nvidia closed in on a $6 trillion market value and AMD gained 2.8%. The 10-year Treasury yield eased 3.6 basis points to 5.275% after Monday's 24-year high, and Brent fell 1.6% to $98.67 as a G7 oil-reserve release eased supply worries. Small caps lagged, with the Russell 2000 down 0.59%.","why_it_matters":"Nvidia, Apple and Microsoft now make up over 21% of the S&P 500, a record concentration, so the index depends heavily on a few AI winners; the Fed's meeting minutes due Wednesday are the next test for yields.","plain_words":["The main US stock index reached its highest level ever.","Big tech companies, especially AI chip makers, did most of the work.","Interest rates on government loans dipped a little, which helped."],"sources":[{"outlet":"TheStreet","url":"https://www.thestreet.com/stock-market-today/stock-market-today-dow-jones-sp-500-nasdaq-updates-oct-06-2026"},{"outlet":"Yahoo Finance","url":"https://finance.yahoo.com/markets/live/stock-market-today-tuesday-october-6-dow-sp-500-nasdaq-080526166.html"},{"outlet":"Bloomberg","url":"https://www.bloomberg.com/news/articles/2026-10-06/nvidia-heads-for-6-trillion-value-with-chipmaker-back-at-record"}],"reading_minutes":1},{"id":"google-constellation","headline":"Google signs 3.6-gigawatt power deal with Constellation Energy; its shares jump 12%","region":"US","whos_who":[{"name":"Google","description":"search and cloud giant, unit of Alphabet"},{"name":"Constellation Energy","description":"biggest US nuclear power operator"},{"name":"PJM","description":"grid serving 13 US states, 67M people"}],"body":"Google agreed a 20-year power purchase agreement *(a long-term contract to buy electricity at set terms)* for 890 MW of new nuclear output, which Constellation will create by investing over $4.3B to upgrade 11 reactors in Illinois, Pennsylvania and New Jersey, with first gains due by 2028. A separate 15-year deal covers another 2,700 MW from Constellation's fleet. Constellation shares rose about 12% and other nuclear stocks such as Oklo and NuScale rallied.","why_it_matters":"AI data centres are driving a race for reliable power; PJM expects peak demand to rise by up to 30 GW by 2030, and tech giants are now paying to expand existing nuclear plants.","plain_words":["AI computers need huge amounts of electricity.","Google promised to buy power from a nuclear company for 20 years, and that company will upgrade its plants to make more.","Investors loved it and pushed the share price up."],"sources":[{"outlet":"DCD","url":"https://www.datacenterdynamics.com/en/news/google-signs-36gw-deal-with-constellation-to-secure-power-in-pjm-service-area/"},{"outlet":"CNBC","url":"https://www.cnbc.com/2026/10/06/google-enters-massive-3point6-gw-power-deal-with-constellation-energy-.html"},{"outlet":"Investing.com","url":"https://www.investing.com/news/company-news/google-signs-20year-nuclear-power-deal-with-constellation-93CH-4933906"}],"reading_minutes":1},{"id":"option-care","headline":"McKesson and CD&R agree $5.8B take-private of home-infusion firm Option Care Health","region":"US","whos_who":[{"name":"McKesson","description":"largest US drug distributor"},{"name":"CD&R","description":"US private-equity firm"},{"name":"Option Care Health","description":"biggest independent US home-infusion provider"}],"body":"The buyers will pay $32.05 per share in cash, a 37.1% premium, valuing the company at about $5.8B including debt; Option Care shares jumped about 33%. CD&R takes a majority stake while McKesson invests $1.4B for 49%, with an option to buy the rest later. Option Care gives patients infusions *(medicine through a drip into a vein)* at home or in small clinics, more than 300,000 a year, and closing is expected in the first half of 2027.","why_it_matters":"It moves McKesson deeper into care delivered at home rather than in hospitals, a cheaper setting that an ageing population is making more important.","plain_words":["A big medicine wholesaler and an investment firm are buying a company that gives patients drip treatments at home.","They are paying much more than the share price, so its shareholders gained a lot in one day.","More medical care is moving from hospitals to people's homes."],"sources":[{"outlet":"KSL / AP","url":"https://www.ksl.com/article/51632936/mckesson-cdr-to-take-infusion-therapy-provider-option-care-private-in-58-billion-deal"},{"outlet":"Motley Fool","url":"https://www.fool.com/investing/2026/10/06/why-option-care-health-stock-skyrocketed-on-tuesday/"},{"outlet":"TheStreet","url":"https://www.thestreet.com/stock-market-today/stock-market-today-dow-jones-sp-500-nasdaq-updates-oct-06-2026"}],"reading_minutes":1},{"id":"ubs-northern-trust","headline":"UBS hands ex-Credit Suisse fund administration to Northern Trust; SMI gains 0.6%","region":"CH","whos_who":[{"name":"UBS","description":"Switzerland's biggest bank"},{"name":"Credit Suisse","description":"rival bank UBS took over in 2023"},{"name":"Northern Trust","description":"US bank for fund services"},{"name":"SMI","description":"index of the 20 biggest Swiss companies"}],"body":"UBS will exit fund administration *(the back-office work of valuing funds and keeping their books)* in Switzerland and Luxembourg, moving the former Credit Suisse businesses to Northern Trust from the second quarter of 2027, with a two-year migration; terms were not disclosed. UBS shares rose 1.4%. The SMI closed up 0.62% at 13,788.93, led by Amrize (+1.7%) and Holcim (+1.4%), though pharma stocks gave up early gains in the afternoon; USD/CHF ended near 0.8308, little changed.","why_it_matters":"It is another step in UBS shrinking the Credit Suisse legacy to cut costs and focus on its core businesses such as wealth management.","plain_words":["UBS is handing a boring but necessary bookkeeping job to an American bank that does it at bigger scale.","That saves UBS money and effort.","Swiss shares rose a bit on the day."],"sources":[{"outlet":"UBS","url":"https://www.ubs.com/global/en/media/display-page-ndp/en-20261006-northern-trust.html"},{"outlet":"finanzen.ch","url":"https://www.finanzen.ch/nachrichten/aktien/aktien-schweiz-schluss-smi-mit-klarem-plus-gesundheitswerte-fallen-zurueck-1036601785"},{"outlet":"Pound Sterling Live","url":"https://www.poundsterlinglive.com/history/USD-CHF-2026"}],"reading_minutes":1}]},{"key":"ai","numeral":"III","title":"AI","note":"Quick hits","stories":[{"id":"mistral-large-4","headline":"Mistral launches Large 4, a 1-trillion-parameter model trained in its own European data centres","region":"EU","whos_who":[{"name":"Mistral","description":"French AI startup, Europe's leading model maker"},{"name":"Nvidia Grace Blackwell","description":"Nvidia's top AI chips"}],"body":"The natively multimodal model (49B active parameters) is in public preview now, with open weights due by the end of October; Mistral trained it on about 3,800 Nvidia Grace Blackwell GPUs and prices it at $1.36 per million input tokens.","why_it_matters":null,"plain_words":["A French company released a very large AI model that can read text and images.","It built and trained it in Europe, without relying on US cloud giants.","Soon anyone will be able to download and run it."],"sources":[{"outlet":"Mistral AI","url":"https://mistral.ai/news/mistral-large-4"},{"outlet":"AI Weekly","url":"https://aiweekly.co/ai-news-today"}],"reading_minutes":1},{"id":"personal-agent-protocol","headline":"Meta and Sierra propose open standard for personal AI agents to deal with businesses","region":"US","whos_who":[{"name":"Meta","description":"owner of Facebook, Instagram, WhatsApp"},{"name":"Sierra","description":"US startup building customer-service AI agents"},{"name":"Walmart, Shopify, Stripe","description":"early partners"}],"body":"The \"Personal Agent Protocol\" sets rules for how a user's AI assistant logs in to a company, what data it may use and what it is allowed to do; the full spec and reference code are due by the end of October.","why_it_matters":null,"plain_words":["Soon your AI assistant might shop or book things for you.","This is a shared set of rules so it can talk safely to stores and companies.","Each company decides what the assistant may do, and you control your data."],"sources":[{"outlet":"PYMNTS","url":"https://www.pymnts.com/news/artificial-intelligence/2026/meta-and-sierra-build-standard-for-how-personal-agents-interact-with-businesses/"},{"outlet":"Sierra","url":"https://sierra.ai/blog/introducing-personal-agent-protocol"}],"reading_minutes":1}]}],"reading_minutes":10,"footer":"compiled by Claude from public reporting · not financial or legal advice","model":"seed: Cowork edition from Notion","generated_at":"2026-10-07T03:15:00Z"}$seed$::jsonb, 1, 'seed: Cowork edition from Notion', '2026-10-07T03:15:00Z')
on conflict (edition_date) do nothing;

insert into public.editions (edition_date, number, big_story, content, schema_version, model, published_at)
values ('2026-10-08', 201, 'Fed minutes show every official backed September''s rate hike and most expect another before year-end, as the 30-year US Treasury yield hit its highest level since 2002.', $seed${"schema_version":1,"date":"2026-10-08","number":201,"volume":1,"big_story":{"text":"Fed minutes show every official backed September's rate hike and most expect another before year-end, as the 30-year US Treasury yield hit its highest level since 2002.","story_id":"fed-minutes"},"markets":{"as_of":"2026-10-07","quotes":[{"name":"S&P 500","level":7801.77,"change":-0.22,"change_unit":"percent","unit":"index"},{"name":"Nasdaq","level":27538.69,"change":-0.22,"change_unit":"percent","unit":"index"},{"name":"SMI","level":13808.42,"change":0.14,"change_unit":"percent","unit":"index"},{"name":"US 10Y","level":5.277,"change":0.8,"change_unit":"bp","unit":"yield"},{"name":"USD/CHF","level":0.8322,"change":0.13,"change_unit":"percent","unit":"fx"},{"name":"Brent","level":100.2,"change":-0.38,"change_unit":"percent","unit":"usd"}]},"sections":[{"key":"corporate_law","numeral":"I","title":"Corporate Law","note":"US focus","stories":[{"id":"sec-climate-investors","headline":"SEC won't charge BlackRock, Vanguard, State Street over Exxon climate push, but warns big investors","region":"US","whos_who":[{"name":"SEC","description":"US stock-market regulator"},{"name":"BlackRock, Vanguard, State Street","description":"world's three biggest fund managers"},{"name":"Climate Action 100+","description":"investor alliance pressing companies on climate"},{"name":"Engine No. 1","description":"activist fund that won Exxon board seats"},{"name":"ExxonMobil","description":"largest US oil company"}],"body":"On Wednesday the SEC closed its probe into the three firms' work with Climate Action 100+ without charges, but published a rare \"report of investigation\" *(a public write-up explaining how the SEC reads the law, without punishing anyone)*. It centres on Exxon's 2021 annual meeting, when the three backed dissident directors put forward by Engine No. 1. The report says joining a group that works to elect dissident directors could cost a big investor its \"passive\" status and the lighter, cheaper ownership-reporting forms that come with it. Corporation Finance director Jim Moloney said shareholders still \"have the right to express their views on a particular topic.\"","why_it_matters":"The index giants own big stakes in almost every US company; the threat of activist-style filing duties will make them even more cautious about teaming up to push boards on climate or other issues.","plain_words":["The three biggest money managers helped climate activists win seats on Exxon's board in 2021.","The regulator won't punish them, but warns: if you team up to change a company's board, you must report like an activist, with more paperwork and rules.","That will probably make them push companies less."],"sources":[{"outlet":"Reuters via Investing.com","url":"https://www.investing.com/news/stock-market-news/us-sec-will-not-pursue-charges-against-climate-group-warns-of-disclosure-obligations-4937029"},{"outlet":"Law360","url":"https://www.law360.com/securities/articles/2535128"},{"outlet":"Bloomberg","url":"https://www.bloomberg.com/news/articles/2026-10-07/sec-warns-activist-investors-after-climate-push-at-exxon-mobil"}],"reading_minutes":1},{"id":"robinhood-ipo","headline":"US government urges Supreme Court to hear Robinhood's fight over its 2021 IPO disclosures","region":"US","whos_who":[{"name":"Robinhood","description":"US app for trading stocks and crypto"},{"name":"Solicitor General","description":"US government's lawyer at the Supreme Court"},{"name":"9th Circuit","description":"federal appeals court for the western US"},{"name":"Section 11","description":"law letting IPO buyers sue over misleading prospectuses"}],"body":"In a brief filed Wednesday, which the Court had invited in June, the Trump administration backed Robinhood's petition in *Robinhood Markets v. Sodha*. Investors who bought in Robinhood's July 2021 IPO say it hid that meme-stock and crypto trading was already slowing before the listing; a district judge dismissed the case in 2024, but the 9th Circuit revived it in 2025. The government says the 9th Circuit wrongly \"collapsed\" two separate elements of an omissions claim. The key question is whether leaving out intra-quarter data *(figures from a quarter that is not yet finished)* can make an IPO prospectus misleading.","why_it_matters":"The government's view carries heavy weight when the justices pick cases; a ruling would set how much up-to-the-minute business information companies must put in IPO documents, and how easily investors can sue afterwards.","plain_words":["People who bought Robinhood shares at its IPO say the company knew business was already slowing and kept quiet.","A lower court let them sue, and now the US government is asking the Supreme Court to step in.","That could change how easily investors can sue companies after they go public."],"sources":[{"outlet":"Law360","url":"https://www.law360.com/securities/articles/2535397"},{"outlet":"TS2","url":"https://ts2.tech/en/robinhood-ipo-suit-goes-to-supreme-court-company-disclosure-rules-on-the-line/"},{"outlet":"Supreme Court docket","url":"https://www.supremecourt.gov/DocketPDF/25/25-944/395566/20260205151117691_PETITION%20FOR%20A%20WRIT%20OF%20CERTIORARI.pdf"}],"reading_minutes":1},{"id":"kalshi-states","headline":"39 states and D.C. urge Supreme Court to let states regulate Kalshi's sports prediction markets","region":"US","whos_who":[{"name":"Kalshi","description":"US platform for trading bets on real-world events"},{"name":"CFTC","description":"US regulator for futures and derivatives"},{"name":"New Jersey","description":"state fighting Kalshi at the Supreme Court"},{"name":"Ohio","description":"first-named state in the coalition"}],"body":"Ohio, 38 other states and Washington, D.C. filed an amicus brief *(a \"friend of the court\" filing by someone not party to the case)* on Wednesday supporting New Jersey's petition in *Flaherty v. KalshiEX*. In April the 3rd Circuit ruled that Kalshi's sports contracts are swaps and that federal commodities law preempts *(overrides)* New Jersey's gambling laws; the 6th and 9th Circuits have since ruled the opposite way. The states say \"the circuits are fractured\" and warn that age limits, exclusion lists and spending caps become unenforceable if the industry wins. Kalshi's response is due 9 November.","why_it_matters":"A Supreme Court ruling would decide whether a fast-growing, multi-billion-dollar betting industry answers to one federal regulator or to 50 state gambling regulators.","plain_words":["Kalshi lets people bet on sports by calling the bets financial contracts, which it says only Washington can regulate.","Most US states disagree and want the Supreme Court to say gambling rules are their job.","Courts have split, so the top court will likely have to decide."],"sources":[{"outlet":"Law360","url":"https://www.law360.com/securities/articles/2535363"},{"outlet":"The Crypto Times","url":"https://www.cryptotimes.io/2026/10/08/39-states-urge-supreme-court-to-review-kalshi-sports-betting-dispute/"},{"outlet":"CDC Gaming","url":"https://cdcgaming.com/brief/tribe-39-state-attorneys-general-latest-to-ask-supreme-court-to-hear-prediction-markets-case/"}],"reading_minutes":1}]},{"key":"finance","numeral":"II","title":"Finance","note":"US & Swiss markets","stories":[{"id":"fed-minutes","headline":"Fed minutes: all officials backed September's rate hike, and most expect another by year-end","region":"US","whos_who":[{"name":"Fed","description":"US central bank, sets interest rates"},{"name":"FOMC","description":"Fed committee that votes on rates"},{"name":"Federal funds rate","description":"Fed's key short-term interest rate"}],"body":"Minutes of the 15–16 September meeting, released Wednesday, confirm the FOMC voted 12–0 to raise rates by a quarter point to 3.75%–4%, the first hike since 2023, with every participant in support. Most judged that another increase \"would likely be appropriate by year end,\" citing inflation still well above the 2% goal, energy prices driven up by the Middle East conflict, and price pressure from the AI investment boom. Officials said labour-market risks had \"diminished and were now broadly balanced.\" Traders put the odds of a hike at the 27–28 October meeting at only about 17–20%, so December is the likelier date.","why_it_matters":"The Fed is in hiking mode, not cutting mode: borrowing stays expensive for companies, home buyers and the US government, which supports the dollar against the franc.","plain_words":["The US central bank raised interest rates last month to fight rising prices, and all its top people agreed.","Most think one more rise is coming before New Year.","That makes loans more expensive for everyone, from families to big companies."],"sources":[{"outlet":"Bloomberg","url":"https://www.bloomberg.com/news/articles/2026-10-07/fed-minutes-show-hawkish-unity-behind-september-rate-hike"},{"outlet":"CNBC","url":"https://www.cnbc.com/2026/10/07/fed-officials-see-another-hike-coming-but-no-sign-as-to-when-minutes-show.html"},{"outlet":"Scripps / NBC26","url":"https://www.nbc26.com/politics/economy/fed-minutes-show-most-officials-expected-another-rate-hike-before-years-end"}],"reading_minutes":1},{"id":"treasury-yields","headline":"Wall Street slips from records as 30-year Treasury yield hits highest level since 2002","region":"US","whos_who":[{"name":"S&P 500","description":"index of 500 biggest US companies"},{"name":"Dow","description":"30 big US blue-chip stocks"},{"name":"US Treasuries","description":"loans to the US government"},{"name":"Caterpillar","description":"maker of construction and mining machines"},{"name":"Constellation Brands","description":"US beer and wine company (Corona, Modelo)"}],"body":"The S&P 500 and Nasdaq each fell 0.22% and the Dow 0.66% a day after record closes, while the small-cap Russell 2000 lost 1.31%. The 30-year Treasury yield closed at 5.66% after touching 5.73% and the 10-year reached 5.36%, both the highest since 2002, while Brent crude traded near $102 after Houthi attacks on Saudi airports and a Gulf of Mexico storm. Caterpillar fell 5.7% on a downgrade, causing most of the Dow's drop, and Constellation Brands slid about 5% despite beating forecasts, as sales in shops and supermarkets declined.","why_it_matters":"Long-term US borrowing costs at 24-year highs push up mortgage and corporate loan rates and make bonds a stronger rival to richly priced stocks.","plain_words":["Stocks dipped a little after hitting record highs.","The bigger news: the US government now pays its highest interest rate in over 20 years to borrow money for 30 years.","When that rate rises, loans for houses and companies get more expensive too."],"sources":[{"outlet":"TheStreet","url":"https://www.thestreet.com/stock-market-today/stock-market-today-dow-jones-sp-500-nasdaq-updates-oct-07-2026"},{"outlet":"Yahoo Finance","url":"https://finance.yahoo.com/markets/live/stock-market-today-wednesday-october-7-dow-sp-500-nasdaq-080241833.html"}],"reading_minutes":1},{"id":"ai-chip-debt","headline":"AI chip debt binge: SpaceX seeks $40B for Nvidia chips, Broadcom over $50B for OpenAI's","region":"US","whos_who":[{"name":"SpaceX","description":"Musk's rocket company, listed since June"},{"name":"Nvidia","description":"biggest AI chipmaker"},{"name":"Broadcom","description":"US chipmaker building custom chips for OpenAI"},{"name":"Oracle","description":"US database and cloud company"},{"name":"Apollo","description":"big US investment and private-credit firm"}],"body":"SpaceX is seeking about $40B — roughly $10B of bank loans and $30B of investment-grade debt *(bonds from borrowers rated safe)* — in a deal led by Apollo to buy Nvidia chips, the FT reported; its shares fell 1.7% on Wednesday. The WSJ added that Broadcom is arranging more than $50B of private credit *(loans from investment funds rather than banks)* with Apollo and Blackstone for OpenAI's custom-chip programme, and that Oracle is talking to Apollo and Goldman Sachs about a vehicle that buys chips and leases them back to it. None of the deals is final yet.","why_it_matters":"The AI build-out is increasingly financed with borrowed money, much of it from private-credit funds and off-balance-sheet structures, which raises the question of who carries the losses if AI demand cools.","plain_words":["AI chips are so expensive that even giant companies are borrowing tens of billions to buy them.","The lenders get paid back over years from the AI business.","If that business slows down, both sides could get hurt."],"sources":[{"outlet":"Reuters via The Star","url":"https://www.thestar.com.my/tech/tech-news/2026/10/07/spacex-seeks-40-billion-to-buy-nvidia-chips-ft-reports"},{"outlet":"WSJ via Investing.com","url":"https://www.investing.com/news/stock-market-news/broadcom-oracle-and-spacex-pursue-blockbuster-debt-deals-amid-ai-buildout--wsj-4937581"},{"outlet":"TheStreet","url":"https://www.thestreet.com/stock-market-today/stock-market-today-dow-jones-sp-500-nasdaq-updates-oct-07-2026"}],"reading_minutes":1},{"id":"samsung-profit","headline":"Samsung guides to record ~$80B quarterly profit as AI memory-chip demand soars","region":"ASIA","whos_who":[{"name":"Samsung Electronics","description":"South Korean maker of chips and phones"},{"name":"HBM","description":"high-bandwidth memory, a key AI chip"},{"name":"DRAM","description":"main type of computer working memory"}],"body":"Samsung's preliminary third-quarter figures show operating profit of about 107.4 trillion won (around $80B), up roughly 780% from a year earlier, on sales of about 195 trillion won, up about 127%. The jump comes from soaring demand and prices for memory chips used in AI data centres, including its new HBM4. Full results follow later this month.","why_it_matters":"It confirms that the AI spending wave is now pouring into memory makers, not just Nvidia, and is one of the largest quarterly profits any company has reported.","plain_words":["Samsung makes the memory chips that AI computers need, and right now everyone wants them.","Prices shot up, so Samsung earned almost nine times more in three months than a year ago.","It shows how much money is flowing into AI."],"sources":[{"outlet":"CNBC","url":"https://www.cnbc.com/2026/10/08/samsung-q3-earnings.html"},{"outlet":"Sammy Fans","url":"https://www.sammyfans.com/2026/10/07/samsung-q3-2026-profit-ai-chip-demand/"},{"outlet":"Bloomberg","url":"https://www.bloomberg.com/news/articles/2026-10-07/samsung-reaches-new-profit-record-with-memory-chip-windfall"}],"reading_minutes":1},{"id":"smi-pharma","headline":"SMI edges up as Novartis and Roche offset slides in UBS and Julius Bär","region":"CH","whos_who":[{"name":"SMI","description":"index of the 20 biggest Swiss companies"},{"name":"Novartis, Roche","description":"Basel pharma giants"},{"name":"UBS","description":"Switzerland's biggest bank"},{"name":"Julius Bär","description":"Zürich private bank for wealthy clients"},{"name":"ABB, Holcim","description":"Swiss engineering and building-materials groups"}],"body":"The SMI rose 0.14% to 13,808.42 in a directionless session weighed down by high bond yields and oil prices. Novartis (+2.4%) and Roche carried the index, while Julius Bär fell 3.9% despite a recently closed FINMA probe and a buyback, UBS lost 3.1% to CHF 39.33 in line with weaker European banks, and ABB and Holcim each dropped 3.3%. The broader SPI slipped 0.04%, and USD/CHF closed around 0.8329, up about 0.14%.","why_it_matters":"Defensive pharma stocks are holding up the Swiss market while banks and cyclical industrials suffer from the global rise in bond yields and oil prices.","plain_words":["Swiss shares ended almost flat.","Medicine makers went up, banks and industrial firms went down.","Investors were nervous about high interest rates and oil, so they bought steady companies and sold riskier ones."],"sources":[{"outlet":"finanzen.ch","url":"https://www.finanzen.ch/nachrichten/aktien/aktien-schweiz-schluss-smi-von-hohen-anleihenrenditen-und-oelpreisen-belastet-1036605761"},{"outlet":"cash.ch","url":"https://www.cash.ch/news/aktien-schweiz-schluss-smi-von-hohen-anleihenrenditen-und-olpreisen-belastet-974926"},{"outlet":"Pound Sterling Live","url":"https://www.poundsterlinglive.com/history/USD-CHF-2026"}],"reading_minutes":1}]},{"key":"ai","numeral":"III","title":"AI","note":"Quick hits","stories":[{"id":"gpt-6-sol-luna","headline":"OpenAI puts GPT-6 Sol and Luna into ChatGPT for all users, with interactive \"Intelligent UI\"","region":"US","whos_who":[{"name":"OpenAI","description":"maker of ChatGPT"},{"name":"GPT-6 Sol / Luna","description":"OpenAI's new everyday ChatGPT models"}],"body":"The October models replace GPT-5.6 Sol and Luna for free and paid users worldwide and add \"Intelligent UI\", which puts tappable buttons, editable charts, calculators and diagrams inside answers — paid tiers from Wednesday, Free and Go users from Thursday. OpenAI's safety report rates both as \"High\" capability in cybersecurity and biology/chemistry.","why_it_matters":null,"plain_words":["ChatGPT got a new brain and a new look.","Instead of only text, answers can now include charts you can change, buttons and little calculators.","Everyone, including free users, gets it this week."],"sources":[{"outlet":"OpenAI Deployment Safety Hub","url":"https://deploymentsafety.openai.com/gpt-6-october/respecting-warnings"},{"outlet":"TechCrunch","url":"https://techcrunch.com/2026/10/07/chatgpt-is-getting-a-lot-more-visual-with-the-launch-of-a-new-interface/"}],"reading_minutes":1},{"id":"chatgpt-teens","headline":"Common Sense Media rates ChatGPT for Teens an \"unacceptable risk\"; OpenAI disputes the tests","region":"US","whos_who":[{"name":"Common Sense Media","description":"US nonprofit rating media and tech for kids"},{"name":"ChatGPT for Teens","description":"ChatGPT version for 13–17-year-olds"},{"name":"OpenAI","description":"maker of ChatGPT"}],"body":"After more than 4,000 test prompts, the group found ChatGPT missed over 1 in 4 cases where a teen needed a crisis referral and that parent alerts often failed to trigger; OpenAI says the testing doesn't reflect how its safeguards work in practice.","why_it_matters":null,"plain_words":["A group that checks whether apps are safe for kids tested the teen version of ChatGPT and said it is not safe enough, especially when a teen needs help.","OpenAI says the test was unfair.","Pressure on AI companies to protect young users keeps growing."],"sources":[{"outlet":"Axios","url":"https://www.axios.com/2026/10/07/chatgpt-teens-safety-risk-common-sense-media"}],"reading_minutes":1}]}],"reading_minutes":11,"footer":"compiled by Claude from public reporting · not financial or legal advice","model":"seed: Cowork edition from Notion","generated_at":"2026-10-08T03:15:00Z"}$seed$::jsonb, 1, 'seed: Cowork edition from Notion', '2026-10-08T03:15:00Z')
